using System;
using System.Collections.Generic;
using System.Data;
using System.IO;
using System.Text;
using System.Web;
using System.Web.Script.Serialization;
using System.Web.SessionState;
using SimsObject;

namespace InformationWeb.Dashboards.API
{
    /// <summary>
    /// API JSON dashboard thống kê tuyển sinh.
    /// action=filters — danh sách Khóa / Chuyên ngành
    /// action=data    — KPI + theo chuyên ngành / khóa / tháng
    /// Bộ lọc: yearId, courseId, specialBranchId, fromDate, toDate
    /// </summary>
    public class StudentAdmissionDashboardApi : IHttpHandler, IReadOnlySessionState
    {
        private const string PERMISSION_VIEW = "frmWebStudentList_View";
        private const string SP_DATA = "DASH_StudentAdmission_GetData";
        private const string SP_FILTER = "DASH_StudentAdmission_GetFilter";

        public void ProcessRequest(HttpContext context)
        {
            context.Response.ContentType = "application/json";
            context.Response.ContentEncoding = Encoding.UTF8;

            if (!DashboardApiBase.EnsureLoggedIn(context))
                return;

            if (!WebGlobal.HasPermission(PERMISSION_VIEW))
            {
                WriteJson(context, false, "Bạn không có quyền xem dashboard thống kê tuyển sinh.", null);
                return;
            }

            try
            {
                string strAction = GetRequestValue(context, "action");
                if (strAction != null && strAction.ToLower() == "filters")
                    HandleFilters(context);
                else
                    HandleData(context);
            }
            catch (Exception)
            {
                WriteJson(context, false, "Có lỗi xảy ra khi tải dữ liệu dashboard.", null);
            }
        }

        private void HandleFilters(HttpContext context)
        {
            string strListType = GetRequestValue(context, "listType");
            string strCourseId = GetRequestValue(context, "courseId");

            if (strListType == null || strListType == "")
            {
                WriteJson(context, false, "Thiếu loại danh sách lọc.", null);
                return;
            }

            byte byListType = Convert.ToByte(strListType);
            SIM_Student objStudent = new SIM_Student();
            DataTable dtbItems = objStudent.GetDataTable(
                SP_FILTER,
                "@CourseID", NormalizeFilter(strCourseId),
                "@ListType", byListType);

            Dictionary<string, object> dicData = new Dictionary<string, object>();
            dicData["items"] = DataTableToList(dtbItems);

            WriteJson(context, true, "", dicData);
        }

        private void HandleData(HttpContext context)
        {
            string strYearId = GetRequestValue(context, "yearId");
            string strCourseId = GetRequestValue(context, "courseId");
            string strSpecialBranchId = GetRequestValue(context, "specialBranchId");
            string strFromDate = GetRequestValue(context, "fromDate");
            string strToDate = GetRequestValue(context, "toDate");

            object objYearId = DBNull.Value;
            if (strYearId != null && strYearId.Trim() != "" && strYearId != "0")
                objYearId = Convert.ToInt32(strYearId);

            Dictionary<string, DataTable> dicTables = GetDashboardData(
                objYearId,
                strCourseId,
                strSpecialBranchId,
                strFromDate,
                strToDate);

            if (dicTables["summary"] == null)
            {
                WriteJson(context, false, "Không tải được dữ liệu từ hệ thống.", null);
                return;
            }

            Dictionary<string, object> dicData = new Dictionary<string, object>();
            dicData["summary"] = DataTableToList(dicTables["summary"]);
            dicData["bySpecialBranch"] = DataTableToList(dicTables["bySpecialBranch"]);
            dicData["byCourse"] = DataTableToList(dicTables["byCourse"]);
            dicData["byMonth"] = DataTableToList(dicTables["byMonth"]);
            dicData["updatedAt"] = DateTime.Now.ToString("dd/MM/yyyy HH:mm");

            WriteJson(context, true, "", dicData);
        }

        private Dictionary<string, DataTable> GetDashboardData(
            object yearId,
            string courseId,
            string specialBranchId,
            string fromDate,
            string toDate)
        {
            Dictionary<string, DataTable> dicResult = new Dictionary<string, DataTable>();
            SIM_Student objStudent = new SIM_Student();

            dicResult["summary"] = CallResultSet(objStudent, yearId, courseId, specialBranchId, fromDate, toDate, 1);
            dicResult["bySpecialBranch"] = CallResultSet(objStudent, yearId, courseId, specialBranchId, fromDate, toDate, 2);
            dicResult["byCourse"] = CallResultSet(objStudent, yearId, courseId, specialBranchId, fromDate, toDate, 3);
            dicResult["byMonth"] = CallResultSet(objStudent, yearId, courseId, specialBranchId, fromDate, toDate, 4);

            return dicResult;
        }

        private DataTable CallResultSet(
            SIM_Student objStudent,
            object yearId,
            string courseId,
            string specialBranchId,
            string fromDate,
            string toDate,
            byte resultSet)
        {
            return objStudent.GetDataTable(
                SP_DATA,
                "@YearID", yearId,
                "@CourseID", NormalizeFilter(courseId),
                "@SpecialBranchID", NormalizeFilter(specialBranchId),
                "@FromDate", NormalizeDate(fromDate),
                "@ToDate", NormalizeDate(toDate),
                "@ResultSet", resultSet);
        }

        private object NormalizeDate(string value)
        {
            if (String.IsNullOrEmpty(value) || value.Trim() == "")
                return DBNull.Value;

            DateTime dtResult;
            if (DateTime.TryParse(value.Trim(), out dtResult))
                return dtResult;

            return DBNull.Value;
        }

        private object NormalizeFilter(string value)
        {
            if (value == null || value.Trim() == "" || value == "0" || value.ToLower() == "all")
                return DBNull.Value;
            return value.Trim();
        }

        private List<Dictionary<string, object>> DataTableToList(DataTable dtb)
        {
            List<Dictionary<string, object>> lstRows = new List<Dictionary<string, object>>();
            if (dtb == null)
                return lstRows;

            int intCol;
            int intRow;
            for (intRow = 0; intRow < dtb.Rows.Count; intRow++)
            {
                Dictionary<string, object> dicRow = new Dictionary<string, object>();
                for (intCol = 0; intCol < dtb.Columns.Count; intCol++)
                {
                    object objValue = dtb.Rows[intRow][intCol];
                    if (objValue == DBNull.Value)
                        dicRow[dtb.Columns[intCol].ColumnName] = null;
                    else if (objValue is DateTime)
                        dicRow[dtb.Columns[intCol].ColumnName] = ((DateTime)objValue).ToString("yyyy-MM-dd");
                    else
                        dicRow[dtb.Columns[intCol].ColumnName] = objValue;
                }
                lstRows.Add(dicRow);
            }
            return lstRows;
        }

        private string GetRequestValue(HttpContext context, string key)
        {
            if (context.Request[key] != null && context.Request[key] != "")
                return context.Request[key];

            string strBody = ReadRequestBody(context);
            if (strBody == null || strBody == "")
                return null;

            JavaScriptSerializer objSerializer = new JavaScriptSerializer();
            Dictionary<string, object> dicBody = objSerializer.Deserialize<Dictionary<string, object>>(strBody);
            if (dicBody == null || !dicBody.ContainsKey(key) || dicBody[key] == null)
                return null;

            return Convert.ToString(dicBody[key]);
        }

        private string ReadRequestBody(HttpContext context)
        {
            if (context.Request.InputStream == null)
                return null;

            context.Request.InputStream.Position = 0;
            StreamReader objReader = new StreamReader(context.Request.InputStream, Encoding.UTF8);
            return objReader.ReadToEnd();
        }

        private void WriteJson(HttpContext context, bool success, string message, object data)
        {
            Dictionary<string, object> dicResponse = new Dictionary<string, object>();
            dicResponse["success"] = success;
            dicResponse["message"] = message;
            dicResponse["data"] = data;

            JavaScriptSerializer objSerializer = new JavaScriptSerializer();
            objSerializer.MaxJsonLength = int.MaxValue;
            context.Response.Write(objSerializer.Serialize(dicResponse));
        }

        public bool IsReusable
        {
            get { return false; }
        }
    }
}

