namespace InformationWeb.Dashboards.Student
{
    public partial class StudentAdmissionDashboard : UserControl
    {
        public string YearClientID
        {
            get { return ddlYearID.ClientID; }
        }

        public string CourseClientID
        {
            get { return "sadCourseFilter"; }
        }

        public string SpecialBranchClientID
        {
            get { return "sadSpecialBranchFilter"; }
        }

        protected void Page_Load(object sender, EventArgs e)
        {
            if (!IsPostBack)
            {
                LoadYearList();
                LoadFilterLists();
            }
        }

        private void LoadYearList()
        {
            DataTable dtbYear = new SIM_YearDAO().Search();
            WebGlobal.InitDropDownList(ddlYearID, dtbYear, SIM_Year.C_YEARID, SIM_Year.C_YEARNAME, "--Chọn--");
            ddlYearID.SelectedValue = WebGlobal.ValueForDropBoxList(SYS_SettingService.GetStringValue("CurrentYearID"));
        }

        private void LoadFilterLists()
        {
            SIM_Student objStudent = new SIM_Student();

            DataTable dtbCourse = objStudent.GetDataTable(
                "DASH_StudentAdmission_GetFilter",
                "@CourseID", DBNull.Value,
                "@ListType", (byte)1);
            rptCourse.DataSource = dtbCourse;
            rptCourse.DataBind();

            DataTable dtbBranch = objStudent.GetDataTable(
                "DASH_StudentAdmission_GetFilter",
                "@CourseID", DBNull.Value,
                "@ListType", (byte)2);
            rptSpecialBranch.DataSource = dtbBranch;
            rptSpecialBranch.DataBind();
        }
    }
}

