/**
 * Dashboard Tổng quan tuyển sinh
 * Load: DASH_StudentAdmission_GetData -> StudentAdmissionDashboardApi.ashx
 */
(function () {
    "use strict";

    var API_URL = "/Dashboards/API/StudentAdmissionDashboardApi.ashx";
    var TEAL = "#1abc9c";
    var BLUE = "#3498db";
    var ORANGE = "#e67e22";
    var RED = "#e74c3c";
    var CHART_PALETTE = [TEAL, BLUE, ORANGE, "#f1c40f", RED, "#9b59b6", "#34495e", "#95a5a6"];
    var TITLE_FONT = "Montserrat, sans-serif";
    var chartInstances = {};
    var eventsBound = false;
    var filterConfig = window.sadDashFilterConfig || {};
    var baseChartOpts = {
        fontFamily: TITLE_FONT,
        foreColor: "#475569",
        toolbar: { show: false },
        width: "100%"
    };

    function getEl(id) {
        return document.getElementById(id);
    }

    function formatNumber(val) {
        var num = parseInt(val, 10);
        if (isNaN(num)) {
            return "0";
        }
        return num.toString().replace(/\B(?=(\d{3})+(?!\d))/g, ".");
    }

    function formatPercent(val) {
        var num = parseFloat(val);
        if (isNaN(num)) {
            return "0%";
        }
        return String(num).replace(".", ",") + "%";
    }

    function showState(state) {
        var loading = getEl("sadDashStateLoading");
        var error = getEl("sadDashStateError");
        var empty = getEl("sadDashStateEmpty");
        var content = getEl("sadDashContent");
        if (loading) {
            loading.className = state === "loading" ? "sad-dash-state" : "sad-dash-state d-none";
        }
        if (error) {
            error.className = state === "error" ? "sad-dash-state" : "sad-dash-state d-none";
        }
        if (empty) {
            empty.className = state === "empty" ? "sad-dash-state" : "sad-dash-state d-none";
        }
        if (content) {
            content.style.display = (state === "ready" || state === "empty") ? "" : "none";
        }
    }

    function setErrorMessage(message) {
        var el = getEl("sadDashErrorMessage");
        if (el) {
            el.textContent = message || "Có lỗi xảy ra.";
        }
    }

    function postJson(payload, callback) {
        var xhr = new XMLHttpRequest();
        xhr.open("POST", API_URL, true);
        xhr.setRequestHeader("Content-Type", "application/json; charset=utf-8");
        xhr.onreadystatechange = function () {
            if (xhr.readyState !== 4) {
                return;
            }
            if (xhr.status !== 200) {
                callback(false, "Không kết nối được API dashboard (HTTP " + xhr.status + ").", null);
                return;
            }
            var response = null;
            try {
                response = JSON.parse(xhr.responseText);
            } catch (e) {
                callback(false, "Phản hồi không hợp lệ từ máy chủ.", null);
                return;
            }
            if (!response || !response.success) {
                if (window.DashboardApiUtils && window.DashboardApiUtils.redirectIfLoginRequired(response)) {
                    return;
                }
                callback(false, response && response.message ? response.message : "Không tải được dữ liệu.", null);
                return;
            }
            callback(true, "", response.data);
        };
        xhr.onerror = function () {
            callback(false, "Lỗi mạng khi gọi API dashboard.", null);
        };
        xhr.send(JSON.stringify(payload));
    }

    function getSelectValue(clientId) {
        if (!clientId) {
            return "";
        }
        var el = document.getElementById(clientId);
        if (!el) {
            return "";
        }
        if (el.classList && el.classList.contains("scs-ms-wrap")) {
            var allCheck = el.querySelector(".scs-ms-check-all");
            if (allCheck && allCheck.checked) {
                return "";
            }
            var checks = el.querySelectorAll(".scs-ms-check:checked");
            var values = [];
            var i;
            for (i = 0; i < checks.length; i++) {
                values.push(checks[i].value);
            }
            return values.join(",");
        }
        return el.value;
    }

    function readFilterConfig() {
        filterConfig = window.sadDashFilterConfig || filterConfig || {};
        return filterConfig;
    }

    function getInputValue(id) {
        var el = getEl(id);
        return el ? el.value : "";
    }

    function destroyChart(key) {
        if (chartInstances[key]) {
            try {
                chartInstances[key].destroy();
            } catch (e) { }
            chartInstances[key] = null;
        }
    }

    function setChartEmpty(chartId, emptyId, isEmpty) {
        var chartEl = getEl(chartId);
        var emptyEl = getEl(emptyId);
        if (chartEl) {
            chartEl.style.display = isEmpty ? "none" : "";
        }
        if (emptyEl) {
            emptyEl.className = isEmpty ? "sad-dash-chart-empty" : "sad-dash-chart-empty d-none";
        }
    }

    function updateMultiSelectCount(container) {
        if (!container || !container.classList || !container.classList.contains("scs-ms-wrap")) {
            return;
        }
        var allCheck = container.querySelector(".scs-ms-check-all");
        var checks = container.querySelectorAll(".scs-ms-check");
        var count = 0;
        var i;
        for (i = 0; i < checks.length; i++) {
            if (checks[i].checked) {
                count++;
            }
        }
        var label = container.querySelector(".scs-ms-label");
        var badge = container.querySelector(".scs-ms-count");
        if (allCheck && allCheck.checked) {
            if (label) {
                label.textContent = container.id === "sadSpecialBranchFilter"
                    ? "Tất cả chuyên ngành"
                    : "Tất cả khóa";
            }
            if (badge) {
                badge.className = "badge bg-secondary scs-ms-count d-none";
            }
        } else {
            if (label) {
                label.textContent = "Đã chọn " + count;
            }
            if (badge) {
                badge.textContent = String(count);
                badge.className = "badge bg-secondary scs-ms-count";
            }
        }
    }

    function updateMultiSelectAllState(container) {
        var checks = container.querySelectorAll(".scs-ms-check");
        var allCheck = container.querySelector(".scs-ms-check-all");
        if (!allCheck) {
            return;
        }
        var allChecked = true;
        var i;
        for (i = 0; i < checks.length; i++) {
            if (!checks[i].checked) {
                allChecked = false;
                break;
            }
        }
        allCheck.checked = allChecked;
    }

    function bindMultiSelectEvents(container) {
        if (!container) {
            return;
        }
        var menu = container.querySelector(".scs-ms-menu");
        if (menu && !menu.getAttribute("data-ms-bound")) {
            menu.setAttribute("data-ms-bound", "1");
            menu.addEventListener("click", function (e) {
                var target = e.target;
                if (!target) {
                    return;
                }
                if (target.classList.contains("scs-ms-check-all")) {
                    var checks = menu.querySelectorAll(".scs-ms-check");
                    var i;
                    for (i = 0; i < checks.length; i++) {
                        checks[i].checked = target.checked;
                    }
                    updateMultiSelectCount(container);
                    if (container.id === "sadCourseFilter") {
                        refreshSpecialBranchDropdown();
                    }
                } else if (target.classList.contains("scs-ms-check")) {
                    updateMultiSelectAllState(container);
                    updateMultiSelectCount(container);
                    if (container.id === "sadCourseFilter") {
                        refreshSpecialBranchDropdown();
                    }
                }
            });
        }
        updateMultiSelectCount(container);
    }

    function bindMultiSelectTriggers() {
        document.addEventListener("click", function (e) {
            var trigger = e.target.closest ? e.target.closest(".scs-ms-trigger") : null;
            var openMenus = document.querySelectorAll(".sad-dash-root .scs-ms-wrap.open");
            var i;
            if (trigger) {
                var wrap = trigger.closest(".scs-ms-wrap");
                if (wrap && wrap.closest(".sad-dash-root")) {
                    for (i = 0; i < openMenus.length; i++) {
                        if (openMenus[i] !== wrap) {
                            openMenus[i].classList.remove("open");
                        }
                    }
                    wrap.classList.toggle("open");
                    e.stopPropagation();
                    return;
                }
            }
            for (i = 0; i < openMenus.length; i++) {
                if (!openMenus[i].contains(e.target)) {
                    openMenus[i].classList.remove("open");
                }
            }
        });
    }

    function fillFilterDropdownPreserve(clientId, rows, valueField, textField, preserveValue) {
        var container = document.getElementById(clientId);
        if (!container) {
            return;
        }
        var menu = container.querySelector(".scs-ms-menu");
        if (!menu) {
            return;
        }
        menu.innerHTML = "";
        var allLabel = document.createElement("label");
        allLabel.className = "scs-ms-item scs-ms-all-item";
        var allCheck = document.createElement("input");
        allCheck.type = "checkbox";
        allCheck.className = "scs-ms-check-all";
        allCheck.checked = true;
        allLabel.appendChild(allCheck);
        allLabel.appendChild(document.createTextNode(" Tất cả"));
        menu.appendChild(allLabel);
        var allDiv = document.createElement("div");
        allDiv.className = "scs-ms-divider";
        menu.appendChild(allDiv);
        var emptyEl = document.createElement("div");
        emptyEl.className = "scs-ms-empty d-none";
        emptyEl.textContent = "Không có dữ liệu";
        menu.appendChild(emptyEl);

        if (rows && rows.length > 0) {
            var i;
            var row;
            for (i = 0; i < rows.length; i++) {
                row = rows[i];
                var value = row[valueField] != null ? String(row[valueField]) : "";
                var text = row[textField] != null ? String(row[textField]) : "";
                if (clientId === "sadSpecialBranchFilter" && row.SpecialBranchShortName) {
                    text = String(row.SpecialBranchShortName) + " - " + text;
                }
                var label = document.createElement("label");
                label.className = "scs-ms-item";
                var check = document.createElement("input");
                check.type = "checkbox";
                check.className = "scs-ms-check";
                check.value = value;
                check.checked = true;
                label.appendChild(check);
                label.appendChild(document.createTextNode(" " + text));
                menu.appendChild(label);
            }
        } else {
            allLabel.className = "scs-ms-item scs-ms-all-item d-none";
            allDiv.className = "scs-ms-divider d-none";
            emptyEl.className = "scs-ms-empty";
        }

        menu.removeAttribute("data-ms-bound");
        bindMultiSelectEvents(container);

        if (preserveValue && String(preserveValue).trim() !== "") {
            var savedValues = String(preserveValue).split(",");
            var checks = container.querySelectorAll(".scs-ms-check");
            var allCb = container.querySelector(".scs-ms-check-all");
            var k;
            for (i = 0; i < checks.length; i++) {
                checks[i].checked = false;
            }
            if (allCb) {
                allCb.checked = false;
            }
            for (i = 0; i < checks.length; i++) {
                for (k = 0; k < savedValues.length; k++) {
                    if (checks[i].value === savedValues[k]) {
                        checks[i].checked = true;
                        break;
                    }
                }
            }
            updateMultiSelectAllState(container);
            updateMultiSelectCount(container);
        }
    }

    function refreshSpecialBranchDropdown() {
        readFilterConfig();
        var courseId = getSelectValue(filterConfig.courseId);
        var current = getSelectValue(filterConfig.specialBranchId);
        postJson({
            action: "filters",
            listType: 2,
            courseId: courseId || ""
        }, function (success, message, data) {
            if (!success) {
                return;
            }
            fillFilterDropdownPreserve(
                filterConfig.specialBranchId,
                data && data.items ? data.items : [],
                "SpecialBranchID",
                "SpecialBranchName",
                current
            );
        });
    }

    function renderKpi(summary) {
        var row = summary && summary.length ? summary[0] : {};
        var enrolled = row.TotalEnrolled || 0;
        var quota = row.TotalQuota || 0;
        var percent = row.PercentQuota || 0;
        var ret = row.ReturnMoneyCount || 0;
        var paid = row.PaidCount || 0;

        var elEnrolled = getEl("sadKpiEnrolled");
        var elQuota = getEl("sadKpiQuota");
        var elPercent = getEl("sadKpiPercent");
        var elReturnPaid = getEl("sadKpiReturnPaid");
        if (elEnrolled) elEnrolled.textContent = formatNumber(enrolled);
        if (elQuota) elQuota.textContent = formatNumber(quota);
        if (elPercent) elPercent.textContent = formatPercent(percent);
        if (elReturnPaid) elReturnPaid.textContent = formatNumber(ret) + " / " + formatNumber(paid);
    }

    function renderTable(rows) {
        var tbody = getEl("sadDashTableBody");
        var countEl = getEl("sadTableCount");
        if (!tbody) {
            return;
        }
        if (!rows || !rows.length) {
            tbody.innerHTML = "<tr><td colspan=\"10\" class=\"text-center text-muted py-4\">Không có dữ liệu.</td></tr>";
            if (countEl) countEl.textContent = "0 chuyên ngành";
            return;
        }
        var html = [];
        var i;
        var row;
        for (i = 0; i < rows.length; i++) {
            row = rows[i];
            html.push(
                "<tr>"
                + "<td class=\"text-center\">" + (i + 1) + "</td>"
                + "<td class=\"sad-code\">" + (row.SpecialBranchShortName || row.SpecialBranchID || "") + "</td>"
                + "<td>" + (row.SpecialBranchName || "") + "</td>"
                + "<td class=\"text-end\">" + formatNumber(row.Quota) + "</td>"
                + "<td class=\"text-end\">" + formatNumber(row.EnrolledCount) + "</td>"
                + "<td class=\"text-end sad-percent\">" + formatPercent(row.PercentQuota) + "</td>"
                + "<td class=\"text-end\">" + formatNumber(row.ReturnMoneyCount) + "</td>"
                + "<td class=\"text-end\">" + formatNumber(row.PaidCount) + "</td>"
                + "<td class=\"text-end\">" + formatNumber(row.MaleCount) + "</td>"
                + "<td class=\"text-end\">" + formatNumber(row.FemaleCount) + "</td>"
                + "</tr>"
            );
        }
        tbody.innerHTML = html.join("");
        if (countEl) {
            countEl.textContent = rows.length + " chuyên ngành";
        }
    }

    function renderChartByCourse(rows) {
        destroyChart("byCourse");
        var isEmpty = !rows || !rows.length || typeof ApexCharts === "undefined";
        setChartEmpty("sadDashChartByCourse", "sadDashChartByCourseEmpty", isEmpty);
        if (isEmpty) {
            return;
        }
        var categories = [];
        var enrolled = [];
        var paid = [];
        var i;
        for (i = 0; i < rows.length; i++) {
            categories.push(rows[i].CourseName || rows[i].CourseID || "");
            enrolled.push(parseInt(rows[i].EnrolledCount, 10) || 0);
            paid.push(parseInt(rows[i].PaidCount, 10) || 0);
        }
        var options = {
            chart: Object.assign({}, baseChartOpts, { type: "bar", height: 320 }),
            series: [
                { name: "Đã tuyển", data: enrolled },
                { name: "Đã đóng HP", data: paid }
            ],
            colors: [TEAL, BLUE],
            plotOptions: {
                bar: { horizontal: true, borderRadius: 4, barHeight: "65%" }
            },
            dataLabels: { enabled: false },
            xaxis: { categories: categories },
            legend: { position: "top" },
            grid: { borderColor: "#e2e8f0" }
        };
        chartInstances.byCourse = new ApexCharts(getEl("sadDashChartByCourse"), options);
        chartInstances.byCourse.render();
    }

    function renderChartByMonth(rows) {
        destroyChart("byMonth");
        var isEmpty = !rows || !rows.length || typeof ApexCharts === "undefined";
        setChartEmpty("sadDashChartByMonth", "sadDashChartByMonthEmpty", isEmpty);
        if (isEmpty) {
            return;
        }
        var categories = [];
        var enrolled = [];
        var ret = [];
        var i;
        for (i = 0; i < rows.length; i++) {
            categories.push(rows[i].MonthLabel || ("T" + rows[i].MonthNo));
            enrolled.push(parseInt(rows[i].EnrolledCount, 10) || 0);
            ret.push(parseInt(rows[i].ReturnMoneyCount, 10) || 0);
        }
        var options = {
            chart: Object.assign({}, baseChartOpts, { type: "area", height: 320 }),
            series: [
                { name: "Đã tuyển", data: enrolled },
                { name: "Rút tiền", data: ret }
            ],
            colors: [BLUE, RED],
            stroke: { curve: "smooth", width: 2 },
            fill: { type: "gradient", gradient: { opacityFrom: 0.35, opacityTo: 0.05 } },
            dataLabels: { enabled: false },
            xaxis: { categories: categories },
            legend: { position: "top" },
            grid: { borderColor: "#e2e8f0" }
        };
        chartInstances.byMonth = new ApexCharts(getEl("sadDashChartByMonth"), options);
        chartInstances.byMonth.render();
    }

    function isEmptyDashboard(data) {
        if (!data || !data.summary || !data.summary.length) {
            return true;
        }
        var total = parseInt(data.summary[0].TotalEnrolled, 10) || 0;
        return total <= 0;
    }

    function renderDashboard(data) {
        var updateEl = getEl("sadDashUpdateTime");
        if (updateEl) {
            updateEl.textContent = data.updatedAt || "--/--/---- --:--";
        }
        renderKpi(data.summary);
        renderTable(data.bySpecialBranch);
        renderChartByCourse(data.byCourse);
        renderChartByMonth(data.byMonth);
    }

    function fetchDashboard() {
        readFilterConfig();
        showState("loading");
        postJson({
            action: "data",
            yearId: getSelectValue(filterConfig.yearId),
            courseId: getSelectValue(filterConfig.courseId),
            specialBranchId: getSelectValue(filterConfig.specialBranchId),
            fromDate: getInputValue(filterConfig.fromDate),
            toDate: getInputValue(filterConfig.toDate)
        }, function (success, message, data) {
            if (!success) {
                setErrorMessage(message);
                showState("error");
                return;
            }
            if (isEmptyDashboard(data)) {
                renderDashboard(data || {});
                showState("empty");
                return;
            }
            renderDashboard(data);
            showState("ready");
        });
    }

    function bindEvents() {
        if (eventsBound) {
            return;
        }
        eventsBound = true;
        bindMultiSelectTriggers();
        bindMultiSelectEvents(getEl("sadCourseFilter"));
        bindMultiSelectEvents(getEl("sadSpecialBranchFilter"));

        var btnLoad = getEl("sadDashBtnLoad");
        var btnRefresh = getEl("sadDashBtnRefresh");
        if (btnLoad) {
            btnLoad.addEventListener("click", fetchDashboard);
        }
        if (btnRefresh) {
            btnRefresh.addEventListener("click", fetchDashboard);
        }
    }

    function init() {
        if (!getEl("sadDashContent")) {
            return;
        }
        bindEvents();
        fetchDashboard();
    }

    if (document.readyState === "loading") {
        document.addEventListener("DOMContentLoaded", init);
    } else {
        init();
    }
})();

