.page-wrapper .page-content .sad-dash-table-wrap {
    max-height: 520px;
    overflow: auto;
}

.page-wrapper .page-content .sad-dash-table thead th {
    position: sticky;
    top: 0;
    z-index: 1;
    background: #f8fafc;
    border-bottom: 1px solid #e2e8f0;
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 0.02em;
    color: #64748b;
    white-space: nowrap;
}

.page-wrapper .page-content .sad-dash-table tbody td {
    font-size: 0.9rem;
    vertical-align: middle;
}

.page-wrapper .page-content .sad-dash-table .sad-code {
    font-weight: 700;
    color: #0f172a;
}

.page-wrapper .page-content .sad-dash-table .sad-percent {
    font-weight: 600;
    color: #0369a1;
}
